struct SearchResult { let index: Int?; let comparisons: Int }
func find(_ target: Int, in values: [Int]) -> SearchResult {
    var comparisons = 0
    for (index, value) in values.enumerated() {
        comparisons += 1
        if value == target { return SearchResult(index: index, comparisons: comparisons) }
    }
    return SearchResult(index: nil, comparisons: comparisons)
}
