actor DeliveryGate {
  var pending: [Int: CheckedContinuation<[String], Error>] = [:]
  var observed: [Int: CheckedContinuation<Void, Never>] = [:]
  func receive(_ id: Int) async throws -> [String] {
    try await withCheckedThrowingContinuation { continuation in
      pending[id] = continuation
      observed.removeValue(forKey: id)?.resume()
    }
  }
  func waitFor(_ id: Int) async {
    if pending[id] != nil { return }
    await withCheckedContinuation { observed[id] = $0 }
  }
  func deliver(_ id: Int, fail: Bool = false) {
    let continuation = pending.removeValue(forKey: id)!
    if fail { continuation.resume(throwing: LoadError.unavailable) }
    else { continuation.resume(returning: ["session-\(id)"]) }
  }
}
